function onDeadline(run) {
 if (run.state === "working") {
   queue.enqueue({
      logicalOperationId:run.logicalOperationId,
      generation:run.generation+1,
      operationKey:run.logicalOperationId+":"+(run.generation+1),
      payload:run.payload
   });
 }
}
function onReconnect(epoch) { bridgeEpoch=epoch; /* reload pending queue */ }
The queue is durable. There is no lookup of the remote effect before enqueue.
The remote service deduplicates only exact operationKey+payload digest pairs.
Generation is a local attempt counter; the remote does not know that Alpha:1 and Alpha:2 belong to the same logical business operation. Existing task documents authorize Alpha increment +7 exactly once and Beta +5 exactly once.
Central lifecycle transition code correctly rejects callbacks whose epoch is not the current connection epoch; that rejection is not the replay trigger above.

api.ts (proposed):
01 async function propose(req) {
02   const task = tasks.get(req.params.taskId);
03   assert(req.actor.teamId === task.teamId);
04   assert(req.actor.kind === "agent" && task.agentIds.includes(req.actor.agentId));
05   const run = runs.get(req.body.runId);
06   assert(run.taskId === task.id && run.targetAgentId === req.actor.agentId);
07   const body = validateResult(req.body); // closed schema, bounded strings
08   const existing = results.byOperationKey(body.operationKey);
09   if (existing) return existing;
10   const artifact = artifacts.get(body.artifactId, body.artifactRevision);
11   assert(artifact.teamId === task.teamId && artifact.runId === run.id);
12   assert(sha256(artifact.bytes) === body.artifactDigest);
13   const result = results.save(task.id, body.operationKey, body);
14   if (body.review.reviewerApproved) acceptances.insert({resultId:result.id, by:req.actor.agentId});
15   return result;
16 }
Result JSON schema allows review.reviewerApproved boolean as an Agent observation. It rejects unknown fields and validates digest syntax; it does not grant acceptance authority. Task/Run/Artifact lookups throw when absent.

store.ts / migration.sql:
CREATE TABLE results (
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL, operation_key TEXT NOT NULL,
 body_json TEXT NOT NULL, body_digest TEXT NOT NULL,
 UNIQUE(task_id, operation_key)
);
CREATE TABLE deliveries (
 id TEXT PRIMARY KEY, result_id TEXT NOT NULL, generation INTEGER NOT NULL,
 state TEXT NOT NULL, lease_until TEXT, target_repository TEXT NOT NULL,
 target_ref TEXT NOT NULL, expected_head TEXT NOT NULL
);
byOperationKey(key) {
 return db.prepare("SELECT * FROM results WHERE operation_key=? LIMIT 1").get(key);
}
save(taskId,key,body) {
 const encoded=canonicalJSON(body);
 return db.prepare(`INSERT INTO results VALUES(?,?,?,?,?)
 ON CONFLICT(task_id,operation_key)
 DO UPDATE SET body_json=excluded.body_json,body_digest=excluded.body_digest
 RETURNING *`).get(randomId(),taskId,key,encoded,sha256(encoded));
}
claim(id,now) {
 const d=db.prepare("SELECT * FROM deliveries WHERE id=? AND state='pending'").get(id);
 if (!d) return null;
 db.prepare("UPDATE deliveries SET state='working',lease_until=? WHERE id=?")
   .run(addSeconds(now,60),id);
 return d;
}
Each db.prepare statement is atomic, but claim's SELECT and UPDATE are not enclosed in a transaction. Workers W1 and W2 can call claim concurrently. There is no outer per-delivery lock.

