01 async function dispatch(id) {
02   const d=claim(id,clock.now()); if(!d) return;
03   const accepted=acceptances.byResult(d.result_id); assert(accepted);
04   const result=results.get(d.result_id);
05   const artifact=artifacts.latest(result.body.artifactId);
06   const grant=grantCache.forDelivery(d.id); // approved and valid at enqueue
07   const receipt=await bridge.apply({operationId:d.id, generation:d.generation,
08     repositoryId:d.target_repository, ref:d.target_ref, expectedHead:d.expected_head,
09     artifactId:artifact.id, artifactDigest:artifact.digest, bytes:artifact.bytes,
10     grantId:grant.id});
11   if(receipt.ok) markCompleted(d.id);
12 }
async function onTransportTimeout(d) {
 db.update(d.id,{state:"pending",generation:d.generation+1});
}
Bridge stores external operation identity as operationId + ":" + generation.
A completed remote effect can precede the Central reply; a timeout discards no remote receipt. Central's timeout handler has no read-only reconciliation step.

bridge.go (abridged proposed Apply):
func Apply(x Request) error {
 if err := AuthenticatePinnedTransport(x.Peer); err != nil { return err }
 binding := RegisteredBinding(x.RepositoryID)
 if binding == nil { return ErrNotRegistered }
 if sha256(x.Bytes) != x.ArtifactDigest { return ErrDigest }
 if RefHead(binding, x.Ref) != x.ExpectedHead { return ErrConflict }
 // x.GrantID was checked by Central when enqueueing; avoid a second disk read.
 receipt, err := ExternalApply(binding, x.Ref, x.Bytes,
     x.OperationID + ":" + strconv.Itoa(x.Generation))
 if err != nil { return err }
 return SaveReceipt(receipt)
}
RegisteredBinding only returns owner-registered repository paths. ExternalApply supports its own operation-key deduplication and atomic expected-head CAS only when the caller supplies expectedHead. This call signature does not pass expectedHead to ExternalApply. Another local writer can change the ref after RefHead returns. Transport pinning authenticates a peer, not a Task-specific owner grant.

